/** Create account */
export function useCreateAccount(options?: Omit<UseMutationOptions<Account, ApiError, Account>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (body: Account) => {
      const result = await api.accounts.createAccount(body);
      if (result.status === 'created') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: accountsKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

